// Regenerate: BX_WRITE_SDK=1 on bentrix-shell's test the_node_bench_is_the_tables, which refuses a stale copy.
'use strict';

const { BentrixError } = require('./client.js');

/** A refusal raised, when the workbench was opened with raiseRefusals: the answer is on it. */
class Refused extends BentrixError {
  constructor(answer) {
    super(answer.reason || answer.outcome);
    this.answer = answer;
  }
}

/**
 * What an order came to. ok unless refused; outcome is the venue's word; a refusal's reason is the venue's own
 * sentence, kind the word a program branches on, remedy what to change and docs the page. raw is the whole answer.
 */
class Answer {
  constructor(raw) {
    const last = (raw && raw.last_answer) || {};
    const get = (k) => (raw && raw[k] !== undefined ? raw[k] : last[k]);
    this.outcome = String(get('outcome') || 'sent');
    for (const k of ['reason', 'kind', 'remedy', 'docs', 'ticket', 'order']) this[k] = get(k) === undefined ? null : get(k);
    this.raw = raw;
  }

  get ok() {
    return this.outcome !== 'refused';
  }
}

function put(a, key, value) {
  if (value !== undefined && value !== null) a[key] = value;
}

function ticketOf(t) {
  return t !== null && typeof t === 'object' ? t.ticket : t;
}

function momentOf(t) {
  return t instanceof Date ? t.getTime() : t;
}

/** A workbench: its orders, its book, its clock and its state, over a connection to a running Bentrix. */
class Bench {
  constructor(client, uri, name, { raiseRefusals = false } = {}) {
    this._c = client;
    this.uri = uri;
    this.name = name === undefined ? null : name;
    this._raise = raiseRefusals;
    this._markets = null;
    this._mounted = false;
  }

  // A workbench with no engine mounted (a clone, through the application) is selected - the window shows it, which is
  // how Bentrix mounts one - and waited for, at most a minute.
  async _mount() {
    if (this._mounted) return;
    this._mounted = true;
    if ((await this._readUri(this.uri)).engine !== 'none') return;
    await this._c.call('select_bench', { bench: this.uri });
    for (let i = 0; i < 600; i++) {
      if ((await this._readUri(this.uri)).engine !== 'none') return;
      await new Promise((r) => setTimeout(r, 100));
    }
  }

  /** The workbench's markets. */
  async markets() {
    if (this._markets === null) {
      const state = await this._readUri(this.uri);
      this._markets = (state.markets || []).map((m) => (typeof m === 'string' ? m : m.symbol));
    }
    return this._markets.slice();
  }

  // Every read through the resource_read tool: a door is anything with call(), the connection or the engine's own.
  _readUri(uri) {
    return this._c.call('resource_read', { uri });
  }

  async _symbol(symbol) {
    if (symbol !== undefined && symbol !== null) return symbol;
    const markets = await this.markets();
    if (markets.length === 1) return markets[0];
    throw new BentrixError(`this workbench holds ${markets.length} markets (${markets.join(', ')}): name the symbol`);
  }

  _answer(raw) {
    const a = new Answer(raw);
    if (!a.ok && this._raise) throw new Refused(a);
    return a;
  }

  _read(tail, after) {
    return this._readUri(`${this.uri}/${tail}` + (after ? `?after=${encodeURIComponent(after)}` : ''));
  }

  async _stream(tail) {
    const out = [];
    let after = null;
    for (;;) {
      const page = await this._read(tail, after);
      const items = page.items || [];
      if (!items.length) return out;
      out.push(...items);
      after = page.next;
      if (after === undefined || after === null) return out;
    }
  }

  /**
   * To the next close: a workbench that has lived through no tick steps one first (a jump never invents a first
   * quote), then a candle of the interval; the closed candle is read back from the window.
   */
  async _step(interval, symbol) {
    const stood = (await this._readUri(this.uri)).cursor_ms;
    const q = ((await this._read('quotes')).items || []).find((x) => x.symbol === symbol);
    if (!q || q.at_ms === undefined || q.at_ms === null) await this._c.call('replay_step', { bench: this.uri, unit: 'tick', n: 1 });
    const moved = await this._c.call('replay_step', { bench: this.uri, unit: 'candle', n: 1, timeframe: interval });
    const now = moved.cursor_ms;
    if (now === undefined || now === null || now === stood) return null;
    const got = await this._c.call('bars_window', { bench: this.uri, symbol, frames: [interval], limit: 1 });
    const rows = got.markets[symbol][interval].rows || [];
    const row = rows[rows.length - 1];
    return row ? { time: row[0], open: row[1], high: row[2], low: row[3], close: row[4], volume: row[5] } : null;
  }

  /** A market buy of lots; sl and tp as prices. */
  async buy(lots, opts = {}) {
    await this._mount();
    const a = { bench: this.uri };
    a.side = "buy";
    put(a, "volume", lots);
    put(a, "symbol", await this._symbol(opts.symbol));
    put(a, "sl", opts.sl);
    put(a, "tp", opts.tp);
    put(a, "tag", opts.tag);
    put(a, "group", opts.group);
    return this._answer(await this._c.call("order_market", a));
  }

  /** A market sell of lots; sl and tp as prices. */
  async sell(lots, opts = {}) {
    await this._mount();
    const a = { bench: this.uri };
    a.side = "sell";
    put(a, "volume", lots);
    put(a, "symbol", await this._symbol(opts.symbol));
    put(a, "sl", opts.sl);
    put(a, "tp", opts.tp);
    put(a, "tag", opts.tag);
    put(a, "group", opts.group);
    return this._answer(await this._c.call("order_market", a));
  }

  /** A pending order: kind buy_limit, sell_limit, buy_stop, sell_stop, buy_stop_limit or sell_stop_limit. */
  async pending(kind, price, lots, opts = {}) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "kind", kind);
    put(a, "price", price);
    put(a, "volume", lots);
    put(a, "symbol", await this._symbol(opts.symbol));
    put(a, "sl", opts.sl);
    put(a, "tp", opts.tp);
    put(a, "stop_limit", opts.stopLimit);
    put(a, "expires_ms", momentOf(opts.expires));
    put(a, "tag", opts.tag);
    put(a, "group", opts.group);
    return this._answer(await this._c.call("order_pending", a));
  }

  /** Only what is named changes: a position's or an order's stop, target, or a pending order's price; 0 removes a level. */
  async modify(ticket, opts = {}) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "ticket", ticketOf(ticket));
    put(a, "sl", opts.sl);
    put(a, "tp", opts.tp);
    put(a, "price", opts.price);
    return this._answer(await this._c.call("order_modify", a));
  }

  /** Close a position, all of it or lots of it, or cancel a pending order. */
  async close(ticket, opts = {}) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "ticket", ticketOf(ticket));
    put(a, "volume", opts.lots);
    return this._answer(await this._c.call("order_close", a));
  }

  /** Close every position, or one market's, or one group's; nothing open is an answer, not a refusal. */
  async closeAll(opts = {}) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "symbol", opts.symbol);
    put(a, "group", opts.group);
    return this._answer(await this._c.call("order_close_all", a));
  }

  /** Close a position and open the same size the other way, as one act. */
  async reverse(ticket) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "ticket", ticketOf(ticket));
    return this._answer(await this._c.call("order_reverse", a));
  }

  /** Stop following a position's trailing stop; its stop stays where the trail left it. */
  async untrail(ticket) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "ticket", ticketOf(ticket));
    return this._answer(await this._c.call("order_untrail", a));
  }

  /** A group of orders under a label: its number, for buy's and close_all's group. */
  async group(label) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "label", label);
    return (await this._c.call("group_open", a))["group"];
  }

  /** A trailing stop at points from the price, the venue's own. */
  async trail(ticket, points) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "ticket", ticketOf(ticket));
    put(a, "points", points);
    return this._answer(await this._c.call("order_trail", a));
  }

  /** Cancel a pending order; the same act as close on an order's ticket. */
  async cancel(ticket) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "ticket", ticketOf(ticket));
    return this._answer(await this._c.call("order_close", a));
  }

  /** What an order would cost and hold - its margin, its money a point, its price - sending nothing. */
  async preview(side, lots, opts = {}) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "side", side);
    put(a, "volume", lots);
    put(a, "symbol", await this._symbol(opts.symbol));
    return await this._c.call("order_preview", a);
  }

  /** What the book holds by market: lots net and gross, each market's notional, the account's ratios. */
  async exposure() {
    await this._mount();
    return this._read("exposure");
  }

  /** The last closed candles of interval, oldest first. */
  async bars(opts = {}) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "timeframe", (opts.interval ?? "M1"));
    put(a, "limit", (opts.limit ?? 100));
    put(a, "symbol", await this._symbol(opts.symbol));
    const page = await this._c.call("bars_get", a);
    const rows = page.bars || [];
    return page.last_forming && rows.length ? rows.slice(0, -1) : rows;
  }

  /** The book: positions, orders and the account. */
  async book() {
    await this._mount();
    return this._read("book");
  }

  /** The open positions. */
  async positions() {
    await this._mount();
    return (await this._read("book")).positions || [];
  }

  /** The resting orders. */
  async orders() {
    await this._mount();
    return (await this._read("book")).orders || [];
  }

  /** The account: balance, equity, margin, free margin, currency. */
  async account() {
    await this._mount();
    return this._read("account");
  }

  /** Every deal, oldest first. */
  async deals() {
    await this._mount();
    return this._stream("deals");
  }

  /** The venue's event log, oldest first. */
  async events() {
    await this._mount();
    return this._stream("events");
  }

  /** Every order the workbench was sent, oldest first: what it became and when. */
  async orderHistory() {
    await this._mount();
    return this._stream("orders");
  }

  /** The market's bid and ask at the clock, or none. */
  async quote(opts = {}) {
    await this._mount();
    const sym = await this._symbol(opts.symbol);
    return ((await this._read("quotes")).items || []).find((q) => q.symbol === sym) || null;
  }

  /** A market's facts as numbers: digits, point, contract, volumes, stops level, swaps, sessions. */
  async spec(opts = {}) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "symbol", await this._symbol(opts.symbol));
    return await this._c.call("symbol_info", a);
  }

  /** Several timeframes at once, closed candles only, each with its forming candle. */
  async window(frames, opts = {}) {
    await this._mount();
    const a = { bench: this.uri };
    a.include_forming = true;
    put(a, "frames", frames);
    put(a, "limit", (opts.limit ?? 100));
    put(a, "symbol", await this._symbol(opts.symbol));
    return await this._c.call("bars_window", a);
  }

  /** Its conditions and their digest. */
  async manifest() {
    await this._mount();
    const a = { bench: this.uri };
    return await this._c.call("bench_manifest", a);
  }

  /** To the next close of interval: the closed candle and where the clock stands, or none where it moves no further. */
  async step(opts = {}) {
    await this._mount();
    return this._step((opts.interval ?? "M1"), await this._symbol(opts.symbol));
  }

  /** Forward to a moment, at most the days' last; where the clock stands. */
  async advance(to) {
    await this._mount();
    const a = { bench: this.uri };
    a.stop_at_end = true;
    put(a, "to_ms", momentOf(to));
    return (await this._c.call("replay_seek", a))["cursor_ms"];
  }

  /** Back to a moment; refused with its door when that would undo a deal, unless undo_deals. */
  async rewind(to, opts = {}) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "to_ms", momentOf(to));
    put(a, "undo_deals", (opts.undoDeals ?? false));
    return await this._c.call("replay_seek", a);
  }

  /** A checkpoint to a file. */
  async save(name) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "path", name);
    return await this._c.call("checkpoint_save", a);
  }

  /** A checkpoint back, refused under other conditions. */
  async load(name) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "path", name);
    return await this._c.call("checkpoint_load", a);
  }

  /** A workbench alike, in this one's state by default. */
  async clone(opts = {}) {
    await this._mount();
    const a = { bench: this.uri };
    put(a, "state", (opts.state ?? true));
    put(a, "name", opts.name);
    const made = await this._c.call("bench_clone", a);
    return new Bench(this._c, made.uri, made.name, { raiseRefusals: this._raise });
  }

  /** Keep where it stands, to watch on the chart: a clone in its state, under a name. */
  async keep(name) {
    await this._mount();
    const a = { bench: this.uri };
    a.state = true;
    put(a, "name", name);
    const made = await this._c.call("bench_clone", a);
    return new Bench(this._c, made.uri, made.name, { raiseRefusals: this._raise });
  }

}

/** A workbench: the one named (its name or its address), else the selected one, else the first. */
async function openBench(client, name, opts = {}) {
  const state = await client.call('get_state', {});
  // A laboratory's workbenches, then a REAL account's (paper among them).
  const every = ['laboratories', 'accounts'].flatMap((area) => state[area] || []).flatMap((home) => home.benches || []);
  const pick = (b) => new Bench(client, b.uri, b.name, opts);
  if (name !== undefined && name !== null) {
    const b = every.find((x) => x.uri === name || x.name === name);
    if (b) return pick(b);
    const names = every.map((x) => JSON.stringify(x.name)).join(', ') || 'none';
    throw new BentrixError(`no workbench is named ${JSON.stringify(name)}; there are ${names}`);
  }
  if (!every.length) throw new BentrixError('the workspace holds no laboratory workbench');
  return pick(every.find((x) => state.selected && x.uri === state.selected) || every[0]);
}

module.exports = { Answer, Bench, Refused, openBench };
